// Revenue Readiness Agent
// Reads configured monetization providers and reports verified revenue only.
// No revenue targets or projections are authorized until Daniel approves a provider/offer and real data exists.

const revenueSources = {
  membership: {
    enabled: $env.MEMBERSHIP_ENABLED === 'true',
    apiKey: $env.MEMBERSHIP_API_KEY,
    provider: $env.MEMBERSHIP_PROVIDER
  },
  shopify: {
    enabled: $env.SHOPIFY_ENABLED === 'true',
    apiKey: $env.SHOPIFY_API_KEY,
    shopDomain: $env.SHOPIFY_SHOP_DOMAIN
  },
  printify: {
    enabled: $env.PRINTIFY_ENABLED === 'true',
    apiKey: $env.PRINTIFY_API_KEY,
    shopId: $env.PRINTIFY_SHOP_ID
  },
  youtube: {
    enabled: $env.YOUTUBE_MONETIZATION_ENABLED === 'true',
    apiKey: $env.YOUTUBE_API_KEY,
    channels: [
      { id: $env.DAX_TRAVELER_CHANNEL_ID, brand: 'dax_traveler' },
      { id: $env.GODS_VESSEL_CHANNEL_ID, brand: 'gods_vessel' },
      { id: $env.TIMEZONE_TRAVELERS_CHANNEL_ID, brand: 'timezone_travelers' },
      { id: $env.ANI_DAX_CHANNEL_ID, brand: 'ani_dax' }
    ]
  },
  affiliates: {
    enabled: $env.AFFILIATE_TRACKING_ENABLED === 'true',
    networks: {
      amazon: { enabled: Boolean($env.AMAZON_AFFILIATE_TAG), tag: $env.AMAZON_AFFILIATE_TAG },
      booking: { enabled: Boolean($env.BOOKING_AFFILIATE_ID), id: $env.BOOKING_AFFILIATE_ID },
      worldnomads: { enabled: Boolean($env.WORLDNOMADS_AFFILIATE_ID), id: $env.WORLDNOMADS_AFFILIATE_ID }
    }
  }
};

const revenueTargets = {
  monthly: {
    month1: 0,
    month2: 0,
    month3: 0,
    month4: 0,
    month5: 0,
    month6: 0
  },
  breakdown: {
    membership: 0,
    ecommerce: 0,
    affiliates: 0,
    youtube: 0,
    services: 0
  },
  rule: 'Targets remain 0 until Daniel approves offers/providers and verified revenue data exists.'
};

const currentTarget = 0;

return {
  revenueSources,
  revenueTargets,
  currentTarget,
  analysisTimestamp: new Date().toISOString(),
  enabledSources: Object.keys(revenueSources).filter(source => revenueSources[source].enabled)
};

// Configure verified revenue source analysis
const revenueData = $('Prepare Revenue Analysis').first();
const currentSource = revenueData.enabledSources[$('Analyze Each Revenue Source').itemIndex];

if (!currentSource) {
  return null;
}

const sourceConfig = revenueData.revenueSources[currentSource];
const targetRevenue = 0;

const apiConfig = {
  membership: {
    url: null,
    headers: {}
  },
  shopify: {
    url: sourceConfig.shopDomain ? 'https://' + sourceConfig.shopDomain + '.myshopify.com/admin/api/2023-10/orders.json?status=any&limit=250&created_at_min=' + new Date(Date.now() - 30 * 24 * 60 * 60 * 1000).toISOString() : null,
    headers: {
      'X-Shopify-Access-Token': sourceConfig.apiKey,
      'Content-Type': 'application/json'
    }
  },
  printify: {
    url: sourceConfig.shopId ? 'https://api.printify.com/v1/shops/' + sourceConfig.shopId + '/orders.json?page=1&limit=100' : null,
    headers: {
      'Authorization': 'Bearer ' + sourceConfig.apiKey,
      'Content-Type': 'application/json'
    }
  },
  youtube: {
    url: sourceConfig.channels ? 'https://www.googleapis.com/youtube/v3/channels?part=statistics&id=' + sourceConfig.channels.map(c => c.id).join(',') + '&key=' + sourceConfig.apiKey : null,
    headers: {
      'Content-Type': 'application/json'
    }
  },
  affiliates: {
    url: null,
    headers: {}
  }
};

return {
  source: currentSource,
  sourceConfig,
  targetRevenue,
  apiConfig: apiConfig[currentSource],
  analysisTimestamp: revenueData.analysisTimestamp
};

// Process verified revenue data only
const sourceConfig = $('Configure Source Analysis').first();
const apiResponse = $('Fetch Revenue Data').first();

let currentRevenue = 0;
let metrics = {};

switch (sourceConfig.source) {
  case 'membership':
    metrics = { status: 'provider_not_configured' };
    break;

  case 'shopify':
    if (apiResponse.orders) {
      currentRevenue = apiResponse.orders.reduce((sum, order) => sum + parseFloat(order.total_price || 0), 0);
      metrics = {
        order_count: apiResponse.orders.length,
        verified_revenue: currentRevenue,
        average_order_value: currentRevenue / (apiResponse.orders.length || 1)
      };
    }
    break;

  case 'printify':
    if (apiResponse.data) {
      currentRevenue = apiResponse.data.reduce((sum, order) => sum + parseFloat(order.total_price || 0), 0);
      metrics = {
        order_count: apiResponse.data.length,
        verified_revenue: currentRevenue,
        average_order_value: currentRevenue / (apiResponse.data.length || 1)
      };
    }
    break;

  case 'youtube':
    if (apiResponse.items) {
      const totalViews = apiResponse.items.reduce((sum, channel) => sum + parseInt(channel.statistics.viewCount || 0), 0);
      currentRevenue = 0;
      metrics = {
        total_views: totalViews,
        verified_revenue: currentRevenue,
        subscriber_count: apiResponse.items.reduce((sum, channel) => sum + parseInt(channel.statistics.subscriberCount || 0), 0),
        note: 'Views are not revenue. YouTube revenue stays 0 unless monetization data is explicitly available.'
      };
    }
    break;

  default:
    currentRevenue = 0;
    metrics = { status: 'unknown_source_or_manual_tracking_required' };
}

const targetRevenue = 0;
const performanceRatio = 0;
const revenueGap = 0;
const recommendations = [];

if (!apiResponse || apiResponse.error || Object.keys(metrics).length === 0) {
  recommendations.push({
    priority: 'high',
    category: 'verification_needed',
    action: 'Connect and verify this provider before recording revenue or conversion claims.',
    impact: 'high'
  });
}

if (sourceConfig.source === 'membership' && !metrics.member_count) {
  recommendations.push({
    priority: 'medium',
    category: 'offer_readiness',
    action: 'Do not promote membership until Daniel approves the offer, pricing, benefits, and provider setup.',
    impact: 'medium'
  });
}

if (sourceConfig.source === 'shopify' && metrics.average_order_value < 50) {
  recommendations.push({
    priority: 'medium',
    category: 'pricing_review',
    action: 'Review pricing and margin only after live product costs, fees, taxes, and shipping are verified.',
    impact: 'medium'
  });
}

return {
  source: sourceConfig.source,
  current_revenue: currentRevenue,
  target_revenue: targetRevenue,
  performance_ratio: performanceRatio,
  revenue_gap: revenueGap,
  metrics,
  recommendations,
  analysis_timestamp: sourceConfig.analysisTimestamp
};

